export async function queryGatewayIntent(queryText) {
  const res = await fetch('http://127.0.0.1:4000/api/query', {
    method: 'POST',
    headers: getAdminHeaders(),
    body: JSON.stringify({ query: queryText })
  });
  return res.json();
}

