  const res = await fetch('/api/admin/cache/stats', { headers: getAdminHeaders() });
  return res.json();
}

export async function fetchAdminCacheEntries() {
  const res = await fetch('/api/admin/cache/entries', { headers: getAdminHeaders() });
  return res.json();
}

