            borderTop: '1px solid #e8e6df',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            background: '#f3f2ee',
            cursor: 'pointer'
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div
              style={{
                width: '32px',
                height: '32px',
                borderRadius: '50%',
                background: '#0e372d',
                color: '#ffffff',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontWeight: '600',
                fontSize: '13px'
              }}
            >
              PS
            </div>
            <div>
              <div style={{ fontSize: '13px', fontWeight: '600', color: '#1a1c19' }}>Pranav Shende</div>
              <div style={{ fontSize: '11px', color: '#787a74' }}>Founder • Executive Access</div>
            </div>
          </div>
          <div style={{ color: '#787a74', fontSize: '13px' }}>•••</div>
        </div>
      </aside>

      {/* ========================================================================= */}
      {/* 2. MAIN APPLICATION CANVAS                                                */}
      {/* ========================================================================= */}
      <main style={{ flex: 1, display: 'flex', flexDirection: 'column', height: '100%', position: 'relative', background: '#f8f7f4', overflow: 'hidden' }}>

        {/* Artistic generative background contour lines */}
        <svg
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: isMobile ? '280px' : '460px',
            height: isMobile ? '280px' : '460px',
            pointerEvents: 'none',
            zIndex: 0,
            opacity: 0.55
          }}
          viewBox="0 0 500 500"
          fill="none"
        >
          <path d="M-50,80 C120,40 180,180 240,120 C300,60 380,220 520,180" stroke="#ded8cd" strokeWidth="1.2" />
          <path d="M-60,140 C100,100 160,240 230,190 C300,140 370,280 530,250" stroke="#e5dfd4" strokeWidth="1" />
          <path d="M-40,200 C110,170 170,300 250,260 C330,220 400,340 540,320" stroke="#eae4d9" strokeWidth="0.8" />
        </svg>

        {/* Top Header Bar */}
        <header
          style={{
            padding: isMobile ? '10px 14px' : '12px 20px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            borderBottom: '1px solid #e8e6df',
            background: 'rgba(248, 247, 244, 0.95)',
            backdropFilter: 'blur(8px)',
            zIndex: 30
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: isMobile ? '8px' : '12px' }}>
            {/* Hamburger Button for Mobile / Collapsed Desktop */}
            {(!sidebarOpen || isMobile) && (
              <button
                onClick={() => setSidebarOpen(true)}
                title="Open menu"
                style={{
                  background: 'transparent',
                  border: 'none',
                  color: '#1a1c19',
                  cursor: 'pointer',
                  padding: '4px',
                  borderRadius: '6px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2">
                  <line x1="3" y1="12" x2="21" y2="12" />
                  <line x1="3" y1="6" x2="21" y2="6" />
                  <line x1="3" y1="18" x2="21" y2="18" />
                </svg>
              </button>
            )}

            <span style={{ fontSize: isMobile ? '13.5px' : '14px', fontWeight: '700', color: '#1a1c19' }}>
              {isMobile ? 'Jarvis AI' : 'Jarvis 1.0 Enterprise'}
            </span>

            {/* Model Selector Dropdown Pill */}
            <div style={{ position: 'relative' }}>
              <div
                onClick={() => setShowModelMenu(!showModelMenu)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '5px',
                  cursor: 'pointer',
                  color: '#1a1c19',
                  fontSize: isMobile ? '11.5px' : '12.5px',
                  fontWeight: '500',
                  padding: isMobile ? '2px 8px' : '3px 10px',
                  borderRadius: '16px',
                  background: '#ffffff',
                  border: '1px solid #e2e0d8',
                  boxShadow: '0 1px 2px rgba(0, 0, 0, 0.04)'
                }}
              >
                <span>{selectedModel}</span>
                <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><polyline points="6 9 12 15 18 9"/></svg>
              </div>

              {showModelMenu && (
                <div
                  style={{
                    position: 'absolute',
                    top: '100%',
                    left: 0,
                    marginTop: '6px',
                    background: '#ffffff',
                    border: '1px solid #e2e0d8',
                    borderRadius: '8px',
                    boxShadow: '0 8px 24px rgba(0, 0, 0, 0.1)',
                    padding: '6px',
                    width: '200px',
                    zIndex: 50
                  }}
                >
                  {['gemini-2.5-pro', 'gemini-3.5-flash', 'gemini-1.5-pro'].map((m) => (
                    <div
                      key={m}
                      onClick={() => { setSelectedModel(m); setShowModelMenu(false); }}
                      style={{
                        padding: '8px 10px',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontSize: '12px',
                        fontWeight: selectedModel === m ? '600' : '400',
                        color: selectedModel === m ? '#0e372d' : '#374151',
                        background: selectedModel === m ? '#e8f5ec' : 'transparent'
                      }}
                    >
                      {m}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Right Status Indicators */}
          <div style={{ display: 'flex', alignItems: 'center', gap: isMobile ? '6px' : '10px' }}>

            {/* DB Health Pill */}
            <span
              title="DB Connected - Redis Active"
              style={{
                fontSize: isMobile ? '11px' : '11.5px',
                padding: isMobile ? '3px 8px' : '4px 10px',
                borderRadius: '16px',
                background: dbStatus === 'HEALTHY' ? '#e8f5ec' : '#fee2e2',
                color: dbStatus === 'HEALTHY' ? '#166534' : '#dc2626',
                border: `1px solid ${dbStatus === 'HEALTHY' ? '#bbf7d0' : '#fecaca'}`,
                display: 'flex',
                alignItems: 'center',
                gap: '5px',
                fontWeight: '600'
              }}
            >
              <span style={{ width: '6px', height: '6px', borderRadius: '50%', background: dbStatus === 'HEALTHY' ? '#16a34a' : '#ef4444' }} />
              {!isMobile && (dbStatus === 'HEALTHY' ? 'DB Connected - Redis Active' : 'System Degraded')}
              {isMobile && 'Live'}
            </span>

            {/* Desktop Only: Chunks Pill */}
            {!isMobile && (
              <span
                style={{
                  fontSize: '11.5px',
                  padding: '4px 10px',
                  borderRadius: '16px',
                  background: '#fef3c7',
                  color: '#92400e',
                  border: '1px solid #fde68a',
                  fontWeight: '500'
                }}
              >
                ⚡ 746 Chunks
              </span>
            )}

            {/* Mobile Only: Workflow Sheet Toggle Button */}
            {isMobile && activeView === 'chat' && showWorkflowPanel && (
              <button
                onClick={() => setMobileWorkflowOpen(true)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px',
                  background: '#0e372d',
                  color: '#ffffff',
                  border: 'none',
                  borderRadius: '14px',
                  padding: '4px 10px',
                  fontSize: '11.5px',
                  fontWeight: '600',
                  cursor: 'pointer'
                }}
              >
                <span style={{ width: '5px', height: '5px', borderRadius: '50%', background: '#4ade80' }} />
                Workflow
              </button>
            )}

            {/* Operations Dashboard Button */}
            {!isMobile ? (
              <button
                onClick={() => setActiveView(activeView === 'founder' ? 'chat' : 'founder')}
                style={{
                  background: '#18181b',
                  border: 'none',
                  color: '#ffffff',
                  padding: '6px 14px',
                  borderRadius: '8px',
                  fontSize: '12px',
                  fontWeight: '500',
                  cursor: 'pointer',
                  transition: 'all 0.15s ease'
                }}
              >
                Operations Dashboard ↗
              </button>
            ) : (
              <button
                onClick={() => setActiveView(activeView === 'founder' ? 'chat' : 'founder')}
                title="Operations Dashboard"
                style={{
                  background: '#18181b',
                  border: 'none',
                  color: '#ffffff',
                  width: '28px',
                  height: '28px',
                  borderRadius: '7px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  cursor: 'pointer'
                }}
              >
                ↗
              </button>
            )}
          </div>
        </header>

        {/* ===================================================================== */}
        {/* SUBVIEW CONTAINER (If activeView !== 'chat')                          */}
        {/* ===================================================================== */}
        {activeView !== 'chat' ? (
          <div style={{ flex: 1, overflowY: 'auto', padding: isMobile ? '12px' : '16px', zIndex: 1 }}>
            {activeView === 'founder' && <FounderDashboard />}
            {activeView === 'knowledge' && <KnowledgeBase />}
            {activeView === 'alerts' && <AlertCenter />}
            {activeView === 'metrics' && <MetricsExplorer />}
            {activeView === 'crosswalk' && <CrosswalkViewer />}
            {activeView === 'sync' && <SyncStatusMonitor />}
            {activeView === 'admin' && <AdminDashboard />}
          </div>
        ) : (
          /* =================================================================== */
          /* CONVERSATIONAL CHATBOT CANVAS                                       */
          /* =================================================================== */
          <div style={{ flex: 1, display: 'flex', height: '100%', overflow: 'hidden', position: 'relative', zIndex: 1 }}>

            {/* Conversation Stream */}
            <div
              style={{
                flex: 1,
                overflowY: 'auto',
                padding: isMobile ? '16px 12px 100px 12px' : '24px 24px 120px 32px',
                display: 'flex',
                flexDirection: 'column'
              }}
            >
              <div style={{ width: '100%', maxWidth: '820px', display: 'flex', flexDirection: 'column', gap: isMobile ? '18px' : '24px' }}>

                {/* Zero State Hero Screen when no active conversation */}
                {messages.length === 0 ? (
                  <div style={{ margin: 'auto', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', width: '100%', maxWidth: '720px', padding: isMobile ? '30px 10px' : '60px 20px', textAlign: 'center' }}>
                    <div style={{ width: '44px', height: '44px', borderRadius: '12px', background: '#0e372d', color: '#ffffff', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '16px', boxShadow: '0 4px 14px rgba(14, 55, 45, 0.25)' }}>
                      <svg width="22" height="22" viewBox="0 0 24 24" fill="#ffffff">
                        <path d="M17 8C8 10 5.9 16.17 3.82 21.34l1.89.66.95-2.3c.48.17.98.3 1.34.3C19 20 22 3 22 3c-1 2-8 2.25-13 3.25S2 11.5 2 13.5s1.75 3.75 1.75 3.75C7 8 17 8 17 8z"/>
                      </svg>
                    </div>
                    <h2 style={{ fontSize: isMobile ? '22px' : '28px', fontWeight: '700', color: '#111827', margin: '0 0 8px 0', letterSpacing: '-0.02em' }}>
                      Where should we begin?
                    </h2>
                    <p style={{ fontSize: isMobile ? '13px' : '14px', color: '#6b7280', margin: '0 0 28px 0', maxWidth: '520px', lineHeight: '1.5' }}>
                      Ask operational questions, investigate wholesale credit limits, audit return grading SOPs, or evaluate dock-to-stock metrics.
                    </p>

                    {/* Prompt suggestion chips */}
                    <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : 'repeat(2, 1fr)', gap: '10px', width: '100%' }}>
                      {samplePrompts.map((promptText, pIdx) => (
                        <button
                          key={pIdx}
                          type="button"
                          onClick={() => {
                            handleSubmit(null, promptText);
                          }}
                          style={{
                            background: '#ffffff',
                            border: '1px solid #e5e5e0',
                            borderRadius: '10px',
                            padding: '12px 14px',
                            textAlign: 'left',
                            cursor: 'pointer',
                            fontSize: '13px',
                            color: '#1f2937',
                            lineHeight: '1.45',
                            boxShadow: '0 1px 3px rgba(0, 0, 0, 0.02)',
                            transition: 'all 0.15s ease'
                          }}
                          onMouseEnter={(e) => {
                            e.currentTarget.style.borderColor = '#0e372d';
                            e.currentTarget.style.boxShadow = '0 3px 10px rgba(14, 55, 45, 0.08)';
                          }}
                          onMouseLeave={(e) => {
                            e.currentTarget.style.borderColor = '#e5e5e0';
                            e.currentTarget.style.boxShadow = '0 1px 3px rgba(0, 0, 0, 0.02)';
                          }}
                        >
                          <div style={{ fontWeight: '600', color: '#111827', marginBottom: '2px', display: 'flex', alignItems: 'center', gap: '6px' }}>
                            <span style={{ color: '#0e372d' }}>✨</span>
                            <span>Query Suggestion</span>
                          </div>
                          <div style={{ color: '#4b5563', fontSize: '12.5px' }}>{promptText}</div>
                        </button>
                      ))}
                    </div>
                  </div>
                ) : (
                  messages.map((m) => (
                    <div
                      key={m.id}
                      style={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: m.role === 'user' ? 'flex-end' : 'flex-start',
                        width: '100%'
                      }}
                    >
                      {/* USER MESSAGE BUBBLE */}
                      {m.role === 'user' ? (
                        <div style={{ display: 'flex', alignItems: 'flex-start', gap: '8px', maxWidth: isMobile ? '90%' : '80%' }}>
                          <div
                            style={{
                              background: '#ebe5df',
                              border: '1px solid #ded9d2',
                              borderRadius: '16px',
                              padding: isMobile ? '10px 14px' : '12px 18px',
                              fontSize: isMobile ? '13.5px' : '14.5px',
                              color: '#1f211e',
                              lineHeight: '1.55',
                              boxShadow: '0 1px 3px rgba(0, 0, 0, 0.03)'
                            }}
                          >
                            <div>{m.content}</div>
                            <div style={{ textAlign: 'right', fontSize: '10.5px', color: '#787a74', marginTop: '4px' }}>
                              {m.timestamp}
                            </div>
                          </div>

                          {/* User Avatar */}
                          <div
                            style={{
                              width: isMobile ? '28px' : '32px',
                              height: isMobile ? '28px' : '32px',
                              borderRadius: '50%',
                              background: '#0e372d',
                              color: '#ffffff',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              fontWeight: '600',
                              fontSize: isMobile ? '11px' : '12px',
                              flexShrink: 0
                            }}
                          >
                            PS
                          </div>
                        </div>
                      ) : (
                        /* ASSISTANT MESSAGE CONTAINER */
                        <div style={{ display: 'flex', gap: isMobile ? '10px' : '14px', width: '100%' }}>
                          {/* Jarvis Avatar */}
                          <div
                            style={{
                              width: isMobile ? '28px' : '32px',
                              height: isMobile ? '28px' : '32px',
                              borderRadius: '50%',
                              background: '#111827',
                              color: '#ffffff',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              fontWeight: 'bold',
                              fontSize: isMobile ? '12px' : '13px',
                              flexShrink: 0
                            }}
                          >
                            J
                          </div>

                          <div style={{ flex: 1, minWidth: 0 }}>
                            {/* Route & Latency Badges */}
                            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px' }}>
                              <span
                                style={{
                                  fontSize: '10.5px',
                                  color: '#6d28d9',
                                  background: '#ede9fe',
                                  border: '1px solid #ddd6fe',
                                  padding: '2px 7px',
                                  borderRadius: '4px',
                                  fontWeight: '700',
                                  letterSpacing: '0.04em'
                                }}
                              >
                                {m.route || 'KNOWLEDGE + DATA'}
                              </span>

                              {m.latencyMs && (
                                <span style={{ fontSize: '11px', color: '#6b7280', display: 'flex', alignItems: 'center', gap: '4px' }}>
                                  ⏱ {(m.latencyMs / 1000).toFixed(1)}s
                                </span>
                              )}

                              {m.isGenerating && (
                                <span style={{ fontSize: '11px', color: '#10b981', display: 'flex', alignItems: 'center', gap: '4px' }}>
                                  <span className="live-pulsing-dot" />
                                  <span>Streaming telemetry...</span>
                                </span>
                              )}
                            </div>

                            {/* Structured Response from Real AI Pipeline */}
                            {m.isGenerating && !m.content ? (
                              <div style={{ color: '#6b7280', fontStyle: 'italic', fontSize: '13.5px', padding: '6px 0' }}>
                                Executing retrieval and dual-synthesis stages...
                              </div>
                            ) : (
                              <StructuredResponse
                                content={m.content}
                                citations={m.citations}
                                onOpenCitation={(c) => setActiveCitation(c)}
                              />
                            )}
                          </div>
                        </div>
                      )}
                    </div>
                  ))
                )}

                <div ref={messagesEndRef} />
              </div>
            </div>

            {/* Desktop Only: Docked AI Execution Workflow Panel (100% Dynamic) */}
            {!isMobile && showWorkflowPanel && (
              <div
                style={{
                  width: '370px',
                  padding: '24px 20px 120px 0',
                  overflowY: 'auto',
                  flexShrink: 0
                }}
              >
                <div style={{ position: 'sticky', top: 0 }}>
                  <ExecutionWorkflow
                    events={liveStreamEvents}
                    isStreaming={isLoading}
                    queryTitle={latestUserQuery}
                    onClose={() => setShowWorkflowPanel(false)}
                  />
                </div>
              </div>
            )}
          </div>
        )}

        {/* ===================================================================== */}
        {/* MOBILE BOTTOM SHEET FOR WORKFLOW PANEL                                */}
        {/* ===================================================================== */}
        {isMobile && mobileWorkflowOpen && (
          <div
            onClick={() => setMobileWorkflowOpen(false)}
            style={{
              position: 'fixed',
              inset: 0,
              zIndex: 110,
              background: 'rgba(0, 0, 0, 0.45)',
              backdropFilter: 'blur(3px)',
              display: 'flex',
              alignItems: 'flex-end',
              justifyContent: 'center'
            }}
          >
            <div
              className="mobile-bottom-sheet"
              onClick={(e) => e.stopPropagation()}
              style={{
                width: '100%',
                maxHeight: '85vh',
                overflowY: 'auto',
                background: '#ffffff',
                borderTopLeftRadius: '20px',
                borderTopRightRadius: '20px',
                padding: '16px',
                boxShadow: '0 -8px 30px rgba(0, 0, 0, 0.15)'
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '10px' }}>
                <div style={{ width: '40px', height: '4px', borderRadius: '2px', background: '#d1d5db' }} />
              </div>
              <ExecutionWorkflow
                events={liveStreamEvents}
                isStreaming={isLoading}
                queryTitle={latestUserQuery}
                onClose={() => setMobileWorkflowOpen(false)}
              />
            </div>
          </div>
        )}

        {/* ===================================================================== */}
        {/* 3. BOTTOM FLOATING CHAT INPUT BAR                                    */}
        {/* ===================================================================== */}
        {activeView === 'chat' && (
          <div
            style={{
              position: 'absolute',
              bottom: isMobile ? '10px' : '24px',
              left: isMobile ? '10px' : (sidebarOpen ? 'calc(50% - 130px)' : '50%'),
              right: isMobile ? '10px' : 'auto',
              transform: isMobile ? 'none' : 'translateX(-50%)',
              width: isMobile ? 'auto' : '90%',
              maxWidth: isMobile ? 'none' : '720px',
              zIndex: 35
            }}
          >
            <form
              onSubmit={handleSubmit}
              style={{
                display: 'flex',
                alignItems: 'center',
                background: '#ffffff',
                borderRadius: '32px',
                padding: isMobile ? '4px 6px 4px 10px' : '6px 10px 6px 12px',
                border: '1px solid #ded9d2',
                boxShadow: '0 8px 30px rgba(0, 0, 0, 0.08)'
              }}
            >
              {/* Add tools / context button */}
              <button
                type="button"
                onClick={() => {}}
                title="Add context or files"
                style={{
                  width: isMobile ? '28px' : '32px',
                  height: isMobile ? '28px' : '32px',
                  borderRadius: '50%',
                  background: '#f3f2ee',
                  border: 'none',
                  color: '#52525b',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  cursor: 'pointer',
                  fontSize: isMobile ? '14px' : '16px',
                  flexShrink: 0
                }}
              >
                +
              </button>

              {/* Chat Input Field */}
              <input
                ref={inputRef}
                type="text"
                value={inputQuery}
                onChange={(e) => setInputQuery(e.target.value)}
                placeholder="Ask Jarvis..."
                disabled={isLoading}
                style={{
                  flex: 1,
                  background: 'transparent',
                  border: 'none',
                  color: '#1a1c19',
                  padding: isMobile ? '6px 10px' : '8px 14px',
                  fontSize: isMobile ? '13.5px' : '14.5px',
                  outline: 'none',
                  fontFamily: 'inherit',
                  minWidth: 0
                }}
              />

              <div style={{ display: 'flex', alignItems: 'center', gap: isMobile ? '5px' : '8px' }}>
                {/* Think reasoning toggle */}
                <button
                  type="button"
                  onClick={() => setIsDeepThink(!isDeepThink)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '4px',
                    padding: isMobile ? '3px 8px' : '4px 10px',
                    borderRadius: '16px',
                    background: isDeepThink ? '#e8f5ec' : '#f3f2ee',
                    color: isDeepThink ? '#0e372d' : '#52525b',
                    border: 'none',
                    fontSize: isMobile ? '11px' : '12px',
                    fontWeight: '500',
                    cursor: 'pointer',
                    whiteSpace: 'nowrap'
                  }}
                >
                  <span>⭘</span>
                  <span>Think</span>
                </button>

                {/* Submit button */}
                <button
                  type="submit"
                  disabled={!inputQuery.trim() || isLoading}
                  style={{
                    width: isMobile ? '32px' : '36px',
                    height: isMobile ? '32px' : '36px',
                    borderRadius: '50%',
                    background: '#0e372d',
                    border: 'none',
                    color: '#ffffff',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    cursor: inputQuery.trim() && !isLoading ? 'pointer' : 'default',
                    opacity: inputQuery.trim() && !isLoading ? 1 : 0.6,
                    transition: 'opacity 0.15s ease',
                    flexShrink: 0
                  }}
                >
                  <svg width={isMobile ? '13' : '15'} height={isMobile ? '13' : '15'} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                    <line x1="12" y1="19" x2="12" y2="5"/>
                    <polyline points="5 12 12 5 19 12"/>
                  </svg>
                </button>
              </div>
            </form>
          </div>
        )}

      </main>
    </div>
  );
}

