import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { UserAuthService } from './user_auth_service.js';
import { authenticateRequest } from './authentication.js';

export async function authRoutes(fastify: FastifyInstance): Promise<void> {
  // 1. Signup
  fastify.post('/api/auth/signup', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { name, email, password } = (request.body as any) || {};
      if (!name || !email || !password) {
        return reply.status(400).send({
          error: 'BAD_REQUEST',
          message: 'Name, email, and password are required.',
        });
      }

      const { user, token, conversationId } = await UserAuthService.signup(name, email, password);

      // Set HTTP-only, SameSite cookie
      reply.setCookie('jarvis_session', token, {
        path: '/',
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: 7 * 24 * 60 * 60, // 7 days
      });

      return reply.status(201).send({
        success: true,
        user,
        token,
        conversationId,
        message: 'Account created successfully.',
      });
    } catch (err: any) {
      const status = err.statusCode || 400;
      return reply.status(status).send({
        error: err.code || 'SIGNUP_FAILED',
        message: err.message || 'Failed to create account.',
      });
    }
  });

  // 2. Login
  fastify.post('/api/auth/login', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const { email, password } = (request.body as any) || {};
      if (!email || !password) {
        return reply.status(400).send({
          error: 'BAD_REQUEST',
          message: 'Email and password are required.',
        });
      }

      const { user, token } = await UserAuthService.login(email, password);

      // Set HTTP-only, SameSite cookie
      reply.setCookie('jarvis_session', token, {
        path: '/',
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: 7 * 24 * 60 * 60,
      });

      return reply.send({
        success: true,
        user,
        token,
        message: 'Logged in successfully.',
      });
    } catch (err: any) {
      const status = err.statusCode || 401;
      return reply.status(status).send({
        error: err.code || 'LOGIN_FAILED',
        message: err.message || 'Authentication failed.',
      });
    }
  });

  // 3. Logout
  fastify.post('/api/auth/logout', async (_request: FastifyRequest, reply: FastifyReply) => {
    reply.clearCookie('jarvis_session', { path: '/' });
    return reply.send({
      success: true,
      message: 'Logged out successfully.',
    });
  });

  // 4. Current Authenticated User (Session Verification)
  fastify.get('/api/auth/me', { preHandler: authenticateRequest }, async (request: FastifyRequest, reply: FastifyReply) => {
    const userContext = request.userContext!;
    const user = await UserAuthService.getUserById(userContext.userId);

    if (!user) {
      // If userContext came from standard admin bearer token, synthesize user object
      return reply.send({
        success: true,
        user: {
          id: userContext.userId,
          name: 'Pranav Shende',
          email: userContext.email,
          role: userContext.role,
        },
      });
    }

    return reply.send({
      success: true,
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        role: userContext.role,
      },
    });
  });
}

import { pool } from '../config/db.js';

export interface ConversationRecord {
  id: string;
  userId: string;
  title: string;
  createdAt: string;
  updatedAt: string;
}

export interface MessageRecord {
  id: string;
  conversationId: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  executionMetadata?: any;
  createdAt: string;
}

export class ConversationService {
  /**
   * List conversations for a specific authenticated user (Strict User-Level Isolation)
   */
  public static async listConversations(userId: string): Promise<ConversationRecord[]> {
    const res = await pool.query(
      `SELECT id, user_id as "userId", title, created_at as "createdAt", updated_at as "updatedAt"
       FROM public.conversations
       WHERE user_id = $1
       ORDER BY updated_at DESC`,
      [userId]
    );
    return res.rows;
  }

  /**
   * Create a new conversation for a user
   */
  public static async createConversation(userId: string, title: string = 'New Chat'): Promise<ConversationRecord> {
    const res = await pool.query(
      `INSERT INTO public.conversations (user_id, title)
       VALUES ($1, $2)
       RETURNING id, user_id as "userId", title, created_at as "createdAt", updated_at as "updatedAt"`,
      [userId, title]
    );
    return res.rows[0];
  }

  /**
   * Get conversation details and complete message history
   */
  public static async getConversationWithMessages(
    userId: string,
    conversationId: string
  ): Promise<{ conversation: ConversationRecord; messages: MessageRecord[] } | null> {
    const convRes = await pool.query(
      `SELECT id, user_id as "userId", title, created_at as "createdAt", updated_at as "updatedAt"
       FROM public.conversations
       WHERE id = $1 AND user_id = $2`,
      [conversationId, userId]
    );

    if (convRes.rows.length === 0) {
      return null;
    }

    const messagesRes = await pool.query(
      `SELECT id, conversation_id as "conversationId", role, content, execution_metadata as "executionMetadata", created_at as "createdAt"
       FROM public.messages
       WHERE conversation_id = $1
       ORDER BY created_at ASC`,
      [conversationId]
    );

    return {
      conversation: convRes.rows[0],
      messages: messagesRes.rows,
    };
  }

  /**
   * Rename conversation
   */
  public static async renameConversation(
    userId: string,
    conversationId: string,
    newTitle: string
  ): Promise<ConversationRecord | null> {
    const res = await pool.query(
      `UPDATE public.conversations
       SET title = $1, updated_at = NOW()
       WHERE id = $2 AND user_id = $3
       RETURNING id, user_id as "userId", title, created_at as "createdAt", updated_at as "updatedAt"`,
      [newTitle.trim(), conversationId, userId]
    );

    if (res.rows.length === 0) return null;
    return res.rows[0];
  }

  /**
   * Delete conversation and cascading messages
   */
  public static async deleteConversation(userId: string, conversationId: string): Promise<boolean> {
    const res = await pool.query(
      `DELETE FROM public.conversations
       WHERE id = $1 AND user_id = $2`,
      [conversationId, userId]
    );
    return (res.rowCount ?? 0) > 0;
  }

  /**
   * Persist a message to database and update conversation timestamp
   */
  public static async persistMessage(
    conversationId: string,
    role: 'user' | 'assistant' | 'system',
    content: string,
    executionMetadata: any = {}
  ): Promise<MessageRecord> {
    const res = await pool.query(
      `INSERT INTO public.messages (conversation_id, role, content, execution_metadata)
       VALUES ($1, $2, $3, $4)
       RETURNING id, conversation_id as "conversationId", role, content, execution_metadata as "executionMetadata", created_at as "createdAt"`,
      [conversationId, role, content, JSON.stringify(executionMetadata || {})]
    );

    // Update conversation timestamp
    await pool.query(
      `UPDATE public.conversations SET updated_at = NOW() WHERE id = $1`,
      [conversationId]
    );

    return res.rows[0];
  }

  /**
   * Auto-update conversation title from initial message if still default 'New Chat'
   */
  public static async maybeUpdateTitleFromPrompt(conversationId: string, prompt: string): Promise<void> {
    const conv = await pool.query('SELECT title FROM public.conversations WHERE id = $1', [conversationId]);
    if (conv.rows.length > 0 && conv.rows[0].title === 'New Chat') {
      const autoTitle = prompt.length > 36 ? prompt.substring(0, 36) + '...' : prompt;
      await pool.query('UPDATE public.conversations SET title = $1, updated_at = NOW() WHERE id = $2', [
        autoTitle,
        conversationId,
      ]);
    }
  }
}

import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { ConversationService } from './conversation_service.js';
import { authenticateRequest } from '../auth/authentication.js';

export async function conversationRoutes(fastify: FastifyInstance): Promise<void> {
  // All conversation routes require authentication
  fastify.addHook('preHandler', authenticateRequest);

  // 1. List conversations for current user
  fastify.get('/api/conversations', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const user = request.userContext!;
      const conversations = await ConversationService.listConversations(user.userId);
      return reply.send({ success: true, conversations });
    } catch (err: any) {
      return reply.status(500).send({ error: 'DB_ERROR', message: err.message });
    }
  });

  // 2. Create new conversation
  fastify.post('/api/conversations', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const user = request.userContext!;
      const { title } = (request.body as any) || {};
      const conversation = await ConversationService.createConversation(user.userId, title || 'New Chat');
      return reply.status(201).send({ success: true, conversation });
    } catch (err: any) {
      return reply.status(500).send({ error: 'DB_ERROR', message: err.message });
    }
  });

  // 3. Get conversation with full message history
  fastify.get('/api/conversations/:id', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const user = request.userContext!;
      const { id } = request.params as { id: string };
      const data = await ConversationService.getConversationWithMessages(user.userId, id);
      if (!data) {
        return reply.status(404).send({ error: 'NOT_FOUND', message: 'Conversation not found or access denied.' });
      }
      return reply.send({ success: true, ...data });
    } catch (err: any) {
      return reply.status(500).send({ error: 'DB_ERROR', message: err.message });
    }
  });

  // 4. Rename conversation
  fastify.patch('/api/conversations/:id', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const user = request.userContext!;
      const { id } = request.params as { id: string };
      const { title } = (request.body as any) || {};
      if (!title || !title.trim()) {
        return reply.status(400).send({ error: 'BAD_REQUEST', message: 'Title is required.' });
      }

      const updated = await ConversationService.renameConversation(user.userId, id, title);
      if (!updated) {
        return reply.status(404).send({ error: 'NOT_FOUND', message: 'Conversation not found or access denied.' });
      }
      return reply.send({ success: true, conversation: updated });
    } catch (err: any) {
      return reply.status(500).send({ error: 'DB_ERROR', message: err.message });
    }
  });

  // 5. Delete conversation
  fastify.delete('/api/conversations/:id', async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      const user = request.userContext!;
      const { id } = request.params as { id: string };
      const deleted = await ConversationService.deleteConversation(user.userId, id);
      if (!deleted) {
        return reply.status(404).send({ error: 'NOT_FOUND', message: 'Conversation not found or access denied.' });
      }
      return reply.send({ success: true, message: 'Conversation deleted.' });
    } catch (err: any) {
      return reply.status(500).send({ error: 'DB_ERROR', message: err.message });
    }
  });
}

