56:   const [inputQuery, setInputQuery] = useState('');
57:   const [isLoading, setIsLoading] = useState(false);
58:   const [liveStreamEvents, setLiveStreamEvents] = useState([]);
59:   const [sidebarOpen, setSidebarOpen] = useState(false);
60:   const [isDeepThink, setIsDeepThink] = useState(false);
