  const totalCost = spend.reduce((acc, row) => acc + parseFloat(row.totalCostUsd || 0), 0);
  const totalTokens = spend.reduce((acc, row) => acc + parseInt(row.totalInputTokens || 0) + parseInt(row.totalOutputTokens || 0), 0);
