460:         let eventType = 'message';
461:         let dataStr = '';
462: 
463:         for (const line of eventLines) {
464:           if (line.startsWith('event: ')) {
465:             eventType = line.substring(7).trim();
466:           } else if (line.startsWith('data: ')) {
467:             dataStr = line.substring(6).trim();
468:           }
469:         }
470: 
471:         if (dataStr) {
472:           try {
473:             const data = JSON.parse(dataStr);
474:             if (eventType === 'workflow_event' && onWorkflowEvent) {
475:               onWorkflowEvent(data);
476:             } else if (eventType === 'complete' && onComplete) {
477:               onComplete(data);
478:             } else if (eventType === 'error' && onError) {
479:               onError(new Error(data.error || 'Server stream error'));
480:             }
481:           } catch (e) {
482:             console.error('Failed to parse SSE payload:', e);
483:           }
484:         }
485:       }
486:     }
487:   } catch (err) {
488:     if (onError) onError(err);
489:   }
