4: export async function authenticateRequest(
5:   request: FastifyRequest,
6:   reply: FastifyReply
7: ): Promise<void> {
8:   const startTime = performance.now();
9:   let rawToken: string | null = null;
10: 
11:   const authHeader = request.headers.authorization;
12:   if (authHeader && authHeader.startsWith('Bearer ')) {
13:     rawToken = authHeader.substring(7).trim();
14:   } else if ((request as any).cookies?.jarvis_session) {
15:     rawToken = (request as any).cookies.jarvis_session;
16:   }
17: 
18:   if (!rawToken) {
19:     reply.status(401).send({
20:       error: 'UNAUTHORIZED',
21:       message: 'Missing or malformed Authorization header or session cookie.',
22:       latencyMs: Math.round((performance.now() - startTime) * 100) / 100,
23:     });
24:     return;
25:   }
26:   const clientTypeHeader = (request.headers['x-jarvis-client'] as string) || 'API';
27:   const clientType = ['SLACK', 'MCP_STREAM', 'MCP_STDIO', 'ADMIN_UI', 'API'].includes(clientTypeHeader)
28:     ? (clientTypeHeader as any)
29:     : 'API';
30: 
31:   const userContext = await IdentityResolver.resolveFromToken(
32:     rawToken,
33:     clientType,
34:     (request.headers['x-request-id'] as string) || undefined
35:   );
36: 
37:   const authDuration = Math.round((performance.now() - startTime) * 100) / 100;
38: 
39:   if (!userContext) {
40:     reply.status(401).send({
41:       error: 'UNAUTHORIZED',
42:       message: 'Invalid, expired, or revoked Jarvis Bearer token.',
43:       latencyMs: authDuration,
44:     });
45:     return;
46:   }
47: 
48:   request.userContext = userContext;
49: }

