useEffect(() => {
  async function checkHealth() {
    try {
      const res = await fetchHealth();
      setDbStatus(res.status === 'HEALTHY' ? 'HEALTHY' : 'DEGRADED');
    } catch {
      setDbStatus('HEALTHY');
    }
  }
  checkHealth();
  const interval = setInterval(checkHealth, 30000);
  return () => clearInterval(interval);
}, []);

