              </div>
              <div style={{ fontSize: '9.5px', color: '#9ca3af', marginTop: '2px' }}>
                Ingests from: WMS Intake (EWR1/ONT1) • QuickBooks AR Ledger • Partner Portal
              </div>
            </div>

            {/* DB Branch B: pgvector Vector Database (HNSW Cosine) */}
            <div
