const bcrypt = require('bcryptjs');
const { pool } = require('./dist/config/db.js');
const { UserAuthService } = require('./dist/auth/user_auth_service.js');

async function main() {
  const hash = bcrypt.hashSync('Jarvis2026!', 10);
  await pool.query('UPDATE public.users SET password_hash = $1 WHERE email = $2', [hash, 'pranav@meridian.com']);
  console.log('Password hash updated for pranav@meridian.com');

  const testLogin = await UserAuthService.login('pranav@meridian.com', 'Jarvis2026!');
  console.log('Login verified successfully:', testLogin.user);
  process.exit(0);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

