const { pool } = require('./dist/config/db.js');

async function clean() {
  const selectQuery = `
    SELECT id, user_id, corporate_email, token_name, status
    FROM jarvis_system.api_tokens
    WHERE user_id LIKE 'wf_%' 
       OR user_id LIKE 'EMP-TEST%' 
       OR user_id LIKE 'EMP-QA%' 
       OR user_id LIKE 'EMP-SEC%' 
       OR user_id LIKE 'EMP-WAREHOUSE%' 
       OR corporate_email LIKE 'marcus%'
       OR corporate_email LIKE '%internal'
       OR status = 'REVOKED';
  `;
  const toDelete = await pool.query(selectQuery);
  console.log(`Found ${toDelete.rows.length} test/revoked/dummy tokens to delete.`);

  const deleteQuery = `
    DELETE FROM jarvis_system.api_tokens
    WHERE user_id LIKE 'wf_%' 
       OR user_id LIKE 'EMP-TEST%' 
       OR user_id LIKE 'EMP-QA%' 
       OR user_id LIKE 'EMP-SEC%' 
       OR user_id LIKE 'EMP-WAREHOUSE%' 
       OR corporate_email LIKE 'marcus%'
       OR corporate_email LIKE '%internal'
       OR status = 'REVOKED';
  `;
  const delRes = await pool.query(deleteQuery);
  console.log(`Successfully deleted ${delRes.rowCount} dummy/test tokens.`);

  const remaining = await pool.query(`
    SELECT id, user_id, corporate_email, token_name, role, status
    FROM jarvis_system.api_tokens
    ORDER BY created_at DESC;
  `);
  console.log(`Remaining clean active tokens (${remaining.rows.length}):`);
  remaining.rows.forEach(t => console.log(` - [${t.status}] ${t.token_name} | ${t.user_id} (${t.corporate_email}) | ${t.role}`));

  process.exit(0);
}

clean().catch(err => {
  console.error(err);
  process.exit(1);
});

