const crypto = require('crypto');
const { pool } = require('./dist/config/db.js');

async function main() {
  const rawToken = 'msc_mcp_founder_sec_7a8f9b1c2d3e4f5a6b7c8d9e0f1a2b3c';
  const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');
  const tokenPrefix = rawToken.substring(0, 18) + '...';

  // Check if hash already exists
  const existing = await pool.query('SELECT id, token_name FROM jarvis_system.api_tokens WHERE token_hash = $1', [tokenHash]);
  if (existing.rows.length === 0) {
    const res = await pool.query(`
      INSERT INTO jarvis_system.api_tokens 
        (user_id, corporate_email, token_hash, token_prefix, token_name, role, department, allowed_scopes, status)
      VALUES 
        ($1, $2, $3, $4, $5, $6, $7, $8, 'ACTIVE')
      RETURNING id, token_name;
    `, [
      'EMP-001',
      'pranav@meridian.com',
      tokenHash,
      tokenPrefix,
      'Executive Founder Master Token',
      'ROLE_FOUNDER',
      'EXECUTIVE',
      ['*']
    ]);
    console.log('Registered Executive Founder Master Token:', res.rows[0]);
  } else {
    console.log('Token already exists:', existing.rows[0]);
  }
  process.exit(0);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

